INSERT INTO public.words (id, word, meaning, detailed_meaning, news_example, hint, related_words, visuals, sources) VALUES
(1121,'국민총생산(GNP)','국적을 기준으로 한 나라 국민이 국내외에서 생산한 최종 생산물의 가치','GNP는 장소가 아니라 국적을 기준으로 생산을 세는 지표다. GDP에 국외순수취요소소득(해외에서 받은 요소소득 - 해외로 준 요소소득)을 더해 구한다. 지금은 국민의 소득 수준을 볼 때 교역조건까지 반영한 GNI를 주로 쓴다.','','ㄱㅁㅊㅅㅅ',ARRAY['국내총생산(GDP)','국민총소득(GNI)','본원소득','최종 생산물']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "GDP는 \"우리 땅에서\" 만든 것,\nGNP는 \"우리 국민이\" 만든 것이에요.\n이름에 N(National)이 붙으면 국적 기준이라고 기억해요."}, {"type": "table", "title": "GDP와 GNP에 들어가는 것", "columns": ["예", "GDP (한국)", "GNP (한국)"], "rows": [["한국인이 미국에서 번 임금", "불포함", "포함"], ["외국인이 한국에서 번 임금", "포함", "불포함"]], "caption": "GNP = GDP + 국외순수취요소소득이에요."}]'::jsonb,ARRAY['tesat']::text[]),
(1122,'케인스 국민소득 결정이론','실제로 쓰는 돈의 크기가 생산과 국민소득을 정한다는 이론','케인스는 가격과 임금이 잘 움직이지 않는 단기에는 수요가 부족하면 값이 내려가는 대신 생산과 고용이 줄어든다고 봤다. 그래서 국민소득은 총지출(소비 + 투자 + 정부지출 + 순수출)과 생산이 같아지는 곳에서 정해진다. 불황에는 정부가 지출을 늘려 수요를 받쳐야 한다는 근거가 됐다.','','ㅋㅇㅅㄱㅁㅅㄷㄱㅈㅇㄹ',ARRAY['유효수요','총지출','승수효과','세이의 법칙']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "1,000개를 만들어도 800개만 팔리면\n결국 800개만 만들게 돼요.\n케인스는 \"수요가 생산을 정한다\"고 봤어요."}, {"type": "table", "title": "고전학파 vs 케인스", "columns": ["구분", "고전학파", "케인스"], "rows": [["가격·임금", "빠르게 움직임", "잘 안 움직임"], ["국민소득을 정하는 것", "공급", "수요(유효수요)"], ["실업", "자발적 실업만", "비자발적 실업도 있음"], ["정부 역할", "작을수록 좋음", "불황엔 적극적으로"]]}, {"type": "text", "title": "왜 중요할까?", "body": "불황 때 정부가 재정지출을 늘리는 이유가 이 이론에서 나와요.\n오늘날 경기부양책의 출발점이에요."}]'::jsonb,ARRAY['tesat']::text[]),
(1123,'유효수요','실제로 살 돈과 의사가 함께 있어 구매로 이어지는 수요','유효수요는 단순히 갖고 싶은 마음이 아니라 지불 능력이 뒷받침된 수요를 말한다. 케인스는 유효수요가 부족하면 기업이 생산을 줄이고 실업이 생긴다고 봤다. 그래서 불황에는 정부가 지출을 늘려 유효수요를 만들어야 한다고 주장했다.','','ㅇㅎㅅㅇ',ARRAY['케인스 국민소득 결정이론','총지출','총수요','승수효과']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "새 차를 갖고 싶어도 살 돈이 없으면 수요로 치지 않아요.\n지갑을 열 수 있는 수요만 생산을 움직여요."}, {"type": "flow", "title": "유효수요가 부족할 때", "steps": ["소비·투자 위축", "팔리지 않은 재고 증가", "기업 생산 축소", "고용·소득 감소"]}]'::jsonb,ARRAY['tesat']::text[]),
(1124,'총지출','가계·기업·정부·해외 부문이 국내 생산물을 사려고 계획한 지출의 합','총지출은 소비, 투자, 정부지출, 순수출을 더한 값으로 AE = C + I + G + (X - M)으로 쓴다. 케인스 모형에서는 생산이 총지출과 같아지는 곳에서 균형국민소득이 정해진다. 생산이 총지출보다 많으면 재고가 쌓여 생산을 줄이고, 적으면 생산을 늘린다.','','ㅊㅈㅊ',ARRAY['총수요','케인스 국민소득 결정이론','생산물시장 균형','기본소비']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "나라 안의 모든 사람과 기업, 정부, 외국이\n우리 물건을 사려고 쓰는 돈을 다 더한 거예요."}, {"type": "table", "title": "총지출의 네 조각", "columns": ["기호", "항목", "예"], "rows": [["C", "소비", "장보기, 외식"], ["I", "투자", "공장, 기계 구입"], ["G", "정부지출", "도로 건설, 공무원 급여"], ["X - M", "순수출", "수출 - 수입"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1125,'균형재정승수','세금을 걷은 만큼 정부가 그대로 쓸 때 국민소득이 늘어나는 배수, 이론상 1','정부가 세금을 100 걷어 100을 쓰면 재정수지는 그대로지만 국민소득은 100만큼 늘어난다. 정부지출은 전액이 바로 지출이 되지만, 세금은 그중 소비하던 부분만큼만 지출을 줄이기 때문이다. 그래서 정부지출 승수와 조세 승수를 더하면 1이 된다.','','ㄱㅎㅈㅈㅅㅅ',ARRAY['승수효과','한계소비성향','재정정책','재정수지']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "세금 100을 걷어 그대로 100을 써도\n경제 전체 소득은 100만큼 늘어나요.\n세금이 줄이는 소비보다 정부가 쓰는 돈이 더 크기 때문이에요."}, {"type": "table", "title": "한계소비성향 0.8일 때", "columns": ["항목", "소득 변화"], "rows": [["정부지출 100", "+500"], ["세금 100", "-400 (소비가 80 줄어서)"], ["합계", "+100"]], "caption": "늘어난 소득이 정부지출 금액과 같아서 승수가 1이에요."}]'::jsonb,ARRAY['tesat']::text[]),
(1126,'기본소비','소득이 0이어도 살기 위해 꼭 하는 최소한의 소비','기본소비는 소비함수 C = 기본소비 + 한계소비성향 × 가처분소득에서 소득과 상관없이 정해진 부분이다. 소득이 없어도 저축을 헐거나 돈을 빌려 먹고 자는 데 쓰는 지출이 여기에 해당한다. 독립소비라고도 하며 기본소비가 늘면 총지출선 전체가 위로 올라간다.','','ㄱㅂㅅㅂ',ARRAY['한계소비성향','평균소비성향','총지출','소비의 비가역성']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "월급이 끊겨도 밥은 먹고 월세는 내야 해요.\n이렇게 소득과 상관없이 나가는 소비가 기본소비예요."}, {"type": "table", "title": "소비함수 C = 50 + 0.8Y", "columns": ["가처분소득", "소비"], "rows": [["0", "50"], ["100", "130"], ["200", "210"]], "caption": "50이 기본소비, 0.8이 한계소비성향이에요."}]'::jsonb,ARRAY['tesat']::text[]),
(1127,'IS 곡선','생산물시장이 균형을 이루는 이자율과 국민소득의 조합을 이은 선','IS 곡선은 투자(I)와 저축(S)이 같아지는, 즉 생산물시장이 균형인 점들을 이자율-국민소득 평면에 이은 선이다. 이자율이 오르면 투자가 줄어 국민소득이 줄기 때문에 우하향한다. 정부지출 증가, 감세, 소비 증가처럼 이자율 밖의 이유로 총지출이 늘면 곡선이 오른쪽으로 이동한다.','','Iㄱㅅ',ARRAY['LM 곡선','IS-LM 모형','생산물시장 균형','구축효과']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "이자가 비싸지면 기업이 공장을 덜 지어요.\n그러면 나라 전체 소득도 줄어요.\n이 관계를 선으로 그린 게 IS 곡선이에요."}, {"type": "flow", "title": "IS 곡선이 우하향하는 이유", "steps": ["이자율↑", "투자↓", "총지출↓", "국민소득↓"]}, {"type": "table", "title": "IS 곡선을 움직이는 것", "columns": ["오른쪽 이동", "왼쪽 이동"], "rows": [["정부지출 증가", "정부지출 감소"], ["세금 감면", "세금 인상"], ["소비·투자 심리 회복", "소비·투자 심리 위축"], ["순수출 증가", "순수출 감소"]], "caption": "이자율 변화는 곡선 위 이동, 그 밖의 총지출 변화는 곡선 자체의 이동이에요."}]'::jsonb,ARRAY['tesat']::text[]),
(1128,'생산물시장 균형','나라 전체의 생산량과 계획된 총지출이 같아진 상태','생산물시장 균형은 생산(Y)과 총지출(AE)이 같아 의도하지 않은 재고가 생기지 않는 상태다. 생산이 지출보다 많으면 재고가 쌓여 생산을 줄이고, 적으면 재고가 줄어 생산을 늘리며 균형을 찾아간다. 케인스 모형에서는 가격이 아니라 재고 변화가 이 조정을 이끈다.','','ㅅㅅㅁㅅㅈㄱㅎ',ARRAY['총지출','IS 곡선','케인스 국민소득 결정이론','국내총생산(GDP)']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "만든 만큼 딱 팔리는 상태예요.\n덜 팔리면 창고에 재고가 쌓이고\n더 팔리면 창고가 비어요."}, {"type": "table", "title": "재고가 보내는 신호", "columns": ["상황", "일어나는 일", "조정"], "rows": [["생산 > 총지출", "재고가 쌓여요", "덜 만들어요"], ["생산 < 총지출", "재고가 줄어요", "더 만들어요"], ["생산 = 총지출", "재고 변화 없음", "균형"]]}, {"type": "line", "title": "총지출선과 45도선 (AE = 100 + 0.8Y)", "unit": "", "x": ["0", "250", "500", "750"], "series": [{"name": "생산 (45도선)", "values": [0, 250, 500, 750]}, {"name": "총지출 AE", "values": [100, 300, 500, 700]}], "caption": "두 선이 만나는 500에서 생산과 지출이 같아져요."}]'::jsonb,ARRAY['tesat']::text[]),
(1129,'화폐의 기능','돈이 교환의 매개, 가치의 척도, 가치 저장 수단으로 하는 역할','화폐는 물물교환 없이 물건을 사고팔게 해 주는 교환의 매개 역할을 한다. 모든 물건 값을 같은 단위로 비교하게 해 주는 가치의 척도이자, 오늘 번 돈을 나중에 쓰게 해 주는 가치 저장 수단이기도 하다. 물가가 크게 오르면 가치 저장 기능이 먼저 흔들린다.','','ㅎㅍㅇㄱㄴ',ARRAY['법정화폐','명목화폐','실물화폐','화폐수요']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "돈이 없으면 쌀을 들고 신발 가게를 찾아다녀야 해요.\n돈 덕분에 바로 사고팔고(매개), 값을 비교하고(척도),\n나중을 위해 모아 둘 수 있어요(저장)."}, {"type": "table", "title": "화폐가 하는 세 가지 일", "columns": ["기능", "뜻"], "rows": [["교환의 매개", "물물교환 없이 돈으로 사고팔아요"], ["가치의 척도", "모든 물건 값을 원 단위로 비교해요"], ["가치 저장", "오늘 번 돈을 나중에 쓸 수 있어요"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1130,'본원통화','중앙은행 창구를 통해 시중에 처음 공급된 돈으로 통화량의 씨앗','본원통화는 한국은행이 공급한 돈으로, 민간이 가진 현금통화와 은행의 지급준비금을 합친 것이다. 형태로 나누면 화폐발행액과 지준예치금의 합과도 같다. 은행의 대출과 예금이 반복되며 본원통화의 몇 배로 통화량이 불어나기 때문에 하이파워드 머니라고도 부른다.','','ㅂㅇㅌㅎ',ARRAY['통화승수','통화량','신용창조','화폐발행액']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "은행들이 대출로 돈을 불리기 전의 \"씨앗 돈\"이에요.\n한국은행 밖으로 돈이 나가면 늘고\n한국은행으로 돌아오면 줄어요."}, {"type": "table", "title": "본원통화를 나누는 두 가지 방법", "columns": ["기준", "식"], "rows": [["누가 들고 있나", "현금통화 + 지급준비금"], ["어떤 형태인가", "화폐발행액 + 지준예치금"]], "caption": "시재금은 지급준비금이면서 화폐발행액에도 들어가요."}, {"type": "table", "title": "본원통화가 늘고 주는 길", "columns": ["부문", "늘어나는 경우", "줄어드는 경우"], "rows": [["정부", "한국은행에서 빌려 씀", "세금을 걷어 한국은행에 맡김"], ["금융", "한국은행이 은행에 대출", "은행이 대출을 갚음"], ["국외", "달러를 원화로 바꿔 줌", "원화를 달러로 바꿈"], ["기타", "한국은행이 국채 매입", "한국은행이 국채 매각"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1131,'시재금','은행이 예금 인출에 대비해 자기 금고에 보관하는 현금','시재금은 은행이 창구나 ATM에서 바로 내줄 수 있도록 직접 보관하는 현금이다. 한국은행에 맡긴 지준예치금과 함께 지급준비금을 이룬다. 은행 밖으로 나와 있는 현금이라 화폐발행액에도 포함된다.','','ㅅㅈㄱ',ARRAY['지준예치금','본원통화','지급준비제도','화폐발행액']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "은행 지점 금고에 넣어 둔 현금이에요.\n손님이 갑자기 돈을 찾으러 와도 바로 내줄 수 있게 준비해 둬요."}, {"type": "table", "title": "지급준비금의 두 조각", "columns": ["구분", "어디에 있나"], "rows": [["시재금", "은행 금고"], ["지준예치금", "한국은행 계좌"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1132,'지준예치금','은행이 지급준비금 가운데 한국은행 계좌에 맡겨 둔 돈','지준예치금은 은행이 지급준비 의무를 지키기 위해 한국은행 당좌예금에 예치한 자금이다. 은행 금고 속 시재금과 합치면 지급준비금이 된다. 화폐발행액과 지준예치금을 더하면 본원통화가 된다.','','ㅈㅈㅇㅊㄱ',ARRAY['시재금','본원통화','지급준비제도','지급준비자산제도']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "은행도 한국은행에 통장이 있어요.\n그 통장에 넣어 둔 준비금이 지준예치금이에요."}, {"type": "table", "title": "한 줄 공식", "columns": ["식", "뜻"], "rows": [["지급준비금 = 시재금 + 지준예치금", "은행이 남겨 둔 돈 전체"], ["본원통화 = 화폐발행액 + 지준예치금", "한국은행이 공급한 돈 전체"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1133,'현금통화','가계와 기업이 은행 밖에서 직접 들고 있는 지폐와 동전','현금통화는 화폐발행액 가운데 은행 금고에 있는 시재금을 뺀, 민간이 보유한 현금이다. 본원통화는 현금통화와 지급준비금으로 이뤄지고, 협의통화(M1)에도 현금통화가 들어간다. 사람들이 현금을 많이 들고 있을수록 은행을 통한 신용창조가 줄어든다.','','ㅎㄱㅌㅎ',ARRAY['본원통화','현금통화비율','협의통화(M1)','화폐발행액']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "내 지갑 속 지폐와 동전,\n가게 금고 속 현금이 현금통화예요.\n은행 금고 안 현금은 시재금이라 따로 세요."}, {"type": "table", "title": "현금은 어디에 있나", "columns": ["위치", "이름"], "rows": [["가계·기업", "현금통화"], ["은행 금고", "시재금"], ["둘을 합치면", "화폐발행액"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1134,'법정지급준비금','법으로 정한 비율만큼 은행이 반드시 남겨 둬야 하는 돈','법정지급준비금은 예금에 법정 지급준비율을 곱한 금액으로, 은행이 대출하지 않고 꼭 쌓아 둬야 하는 최소 준비금이다. 지급준비율이 10%이고 예금이 100억 원이면 10억 원이 법정지급준비금이다. 실제 지급준비율은 예금 종류마다 다르게 정해져 있다.','','ㅂㅈㅈㄱㅈㅂㄱ',ARRAY['초과지급준비금','지급준비제도','통화승수','시재금']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "은행이 예금을 전부 빌려주면 손님이 돈을 찾을 때 곤란해요.\n그래서 법으로 정한 만큼은 꼭 남겨 두게 해요."}, {"type": "table", "title": "예금 100억 원, 지급준비율 10%라면", "columns": ["구분", "금액"], "rows": [["법정지급준비금", "10억 원"], ["대출할 수 있는 돈", "90억 원"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1135,'초과지급준비금','은행이 법으로 정한 수준보다 더 남겨 둔 준비금','실제 지급준비금은 법정지급준비금과 초과지급준비금을 더한 것이다. 은행은 예대마진으로 돈을 벌기 때문에 보통 초과분을 적게 두려 하지만, 경기가 불안하면 대출 대신 쌓아 두기도 한다. 초과지급준비금이 많아지면 통화승수가 작아져 통화량이 덜 늘어난다.','','ㅊㄱㅈㄱㅈㅂㄱ',ARRAY['법정지급준비금','지급준비제도','통화승수','예대금리차(예대마진)']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "꼭 남길 돈보다 더 남겨 둔 여유분이에요.\n은행이 \"지금은 빌려주기 불안하다\"고 느끼면 늘어나요."}, {"type": "table", "title": "실제 지급준비금의 구성", "columns": ["구분", "뜻"], "rows": [["법정지급준비금", "법으로 꼭 남겨야 하는 돈"], ["초과지급준비금", "그보다 더 남긴 돈"]], "caption": "실제 지급준비금 = 법정 + 초과예요."}]'::jsonb,ARRAY['tesat']::text[]),
(1136,'현금통화비율','사람들이 통화 가운데 예금 대신 현금으로 들고 있는 몫의 비율','현금통화비율은 통화량에서 현금통화가 차지하는 비중을 말한다. 현금으로 들고 있는 돈은 은행으로 돌아와 다시 대출되지 않기 때문에 이 비율이 높을수록 통화승수가 작아진다. 현금까지 고려한 통화승수는 1 ÷ (c + z(1 - c))로, c는 현금통화비율, z는 지급준비율이다.','','ㅎㄱㅌㅎㅂㅇ',ARRAY['통화승수','현금통화','신용창조','본원통화']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "월급을 통장에 두지 않고 장롱에 넣어 두면\n은행이 그 돈을 빌려줄 수 없어요.\n그래서 현금 비중이 크면 통화량이 덜 불어나요."}, {"type": "table", "title": "지급준비율 10%일 때 통화승수", "columns": ["현금통화비율", "통화승수"], "rows": [["0%", "10"], ["20%", "약 3.6"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1137,'화폐공급곡선','이자율 수준별로 시중에 공급되는 화폐의 양을 나타낸 선, 교과서에선 수직','화폐공급은 중앙은행이 정한다고 보기 때문에 교과서에서는 이자율과 상관없는 수직선으로 그린다. 본원통화가 늘거나 지급준비율 인하 등으로 통화승수가 커지면 오른쪽으로 이동한다. 이자율이 오를 때 예금이 늘어 통화승수가 커진다고 보는 내생적 화폐공급설에서는 우상향으로 그리기도 한다.','','ㅎㅍㄱㄱㄱㅅ',ARRAY['화폐수요','화폐시장 균형','본원통화','통화승수']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "시중에 돈을 얼마나 풀지는 한국은행이 정해요.\n이자율이 높든 낮든 공급량은 그대로라서\n그래프에선 세로로 선 직선이에요."}, {"type": "table", "title": "화폐공급곡선이 움직일 때", "columns": ["변화", "곡선"], "rows": [["본원통화 증가", "오른쪽 이동"], ["통화승수 증가 (지급준비율↓ 등)", "오른쪽 이동"], ["이자율 변화", "움직이지 않음"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1138,'화폐수요','채권 같은 자산 대신 현금·예금 형태로 들고 있으려는 돈의 양','이는 돈을 쓰려는 것이 아니라 특정 시점에 돈으로 보유하려는 양을 뜻하는 저량 개념이다. 고전학파는 소득에만 비례한다고 봤고, 케인스는 소득과 함께 이자율에도 영향을 받는다고 봤다. 이자율이 오르면 돈을 들고 있는 기회비용이 커져 보유량이 줄어든다.','','ㅎㅍㅅㅇ',ARRAY['유동성 선호설','화폐수요 함수','화폐보유 동기','유동성 함정']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "이자를 주는 채권 대신\n이자 없는 돈을 지갑과 통장에 두려는 마음이에요.\n\"얼마나 쓰나\"가 아니라 \"지금 얼마 들고 있나\"예요."}, {"type": "table", "title": "학파별 생각", "columns": ["학파", "정하는 것", "곡선 모양"], "rows": [["고전학파", "소득만", "수직 (이자율과 무관)"], ["케인스", "소득 + 이자율", "우하향"], ["유동성 함정", "이자율이 바닥", "수평"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1139,'유동성 선호설','돈을 들고 있으려는 수요와 화폐공급이 이자율을 정한다는 케인스 이론','케인스는 사람들이 거래적, 예비적, 투기적 동기로 돈을 보유한다고 봤다. 이자율은 저축과 투자가 아니라 화폐시장에서 화폐수요와 화폐공급이 같아지는 곳에서 정해진다. 이 이론에서는 통화량 변화가 이자율을 거쳐 실물 경제에 영향을 준다.','','ㅇㄷㅅㅅㅎㅅ',ARRAY['화폐수요','화폐보유 동기','대부자금설','유동성 함정']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "이자율은 \"돈을 들고 있는 값\"이에요.\n돈을 들고 싶어 하는 사람이 많으면 값(이자율)이 오르고\n돈이 넘치면 내려가요."}, {"type": "table", "title": "이자율은 어디서 정해질까", "columns": ["학파", "시장", "결정 방식"], "rows": [["케인스", "화폐시장", "화폐수요 = 화폐공급 (유동성 선호설)"], ["고전학파", "대부자금시장", "저축 = 투자 (대부자금설)"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1140,'화폐보유 동기','사람들이 돈을 들고 있는 이유로 케인스가 나눈 거래적·예비적·투기적 동기','거래적 동기는 물건을 사기 위해, 예비적 동기는 갑작스러운 지출에 대비하기 위해 돈을 들고 있는 것으로 둘 다 소득이 늘면 커진다. 투기적 동기는 채권값이 내릴 것 같을 때 채권 대신 돈을 들고 기다리는 것으로 이자율에 따라 달라진다. 이자율이 낮을수록 앞으로 오를 것으로 예상해 투기적 화폐수요가 늘어난다.','','ㅎㅍㅂㅇㄷㄱ',ARRAY['화폐수요','유동성 선호설','유동성 함정','기회비용']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "장 보려고(거래적), 혹시 몰라서(예비적),\n채권을 싸게 살 때를 기다리려고(투기적)\n사람들은 돈을 들고 있어요."}, {"type": "table", "title": "세 가지 동기", "columns": ["동기", "뜻", "정하는 것"], "rows": [["거래적 동기", "물건을 사려고", "소득"], ["예비적 동기", "갑작스러운 일에 대비", "소득"], ["투기적 동기", "채권값이 내릴 것 같아 기다림", "이자율"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1141,'화폐의 중립성','통화량이 늘어도 물가만 오르고 생산·고용 같은 실물 경제는 바뀌지 않는다는 생각','고전학파는 화폐수량설(MV = PY)에서 유통속도와 생산량이 일정하다고 보고, 통화량이 늘면 물가만 비례해 오른다고 봤다. 돈은 실물 경제를 덮은 베일일 뿐이라는 뜻에서 화폐 베일관이라고도 한다. 오늘날에는 단기에는 돈이 실물에 영향을 주지만 장기에는 중립성이 성립한다는 견해가 많다.','','ㅎㅍㅇㅈㄹㅅ',ARRAY['통화유통속도','통화량','정책 무력성 명제','실질통화량']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "모든 가격표에 0을 하나씩 더 붙여도\n빵 개수나 일자리 수는 그대로예요.\n돈의 양은 숫자 단위만 바꾼다는 생각이에요."}, {"type": "flow", "title": "고전학파의 설명", "steps": ["통화량↑", "V·Y는 일정", "물가 P만↑", "생산·고용 그대로"]}, {"type": "text", "title": "왜 중요할까?", "body": "돈을 풀어 경기를 살리는 정책이 장기에도 통하는지를 가르는 기준이에요.\n장기엔 물가만 올린다는 결론으로 이어져요."}]'::jsonb,ARRAY['tesat']::text[]),
(1142,'화폐시장 균형','화폐수요와 화폐공급이 같아져 균형 이자율이 정해진 상태','화폐공급곡선(수직)과 우하향하는 화폐수요곡선이 만나는 곳에서 균형 이자율이 정해진다. 이자율이 균형보다 높으면 남는 돈으로 채권을 사 채권값이 오르고 이자율이 내려가며, 낮으면 반대로 움직인다. 통화량이 늘거나 화폐수요가 줄면 균형 이자율이 내려간다.','','ㅎㅍㅅㅈㄱㅎ',ARRAY['화폐수요','화폐공급곡선','LM 곡선','유동성 선호설']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "돈이 남으면 사람들이 채권을 사서 이자율이 내려가고\n돈이 모자라면 채권을 팔아 이자율이 올라가요.\n그렇게 맞춰진 이자율이 균형 이자율이에요."}, {"type": "table", "title": "무엇이 바뀌면 이자율은?", "columns": ["변화", "곡선", "이자율"], "rows": [["통화량 증가", "공급 오른쪽", "하락"], ["물가 상승", "실질 공급 왼쪽", "상승"], ["소득 증가", "수요 오른쪽", "상승"], ["신용카드 보급", "수요 왼쪽", "하락"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1143,'화폐수요 함수','물가·소득·이자율이 사람들이 들고 있으려는 돈의 양을 어떻게 정하는지 나타낸 식','명목 화폐수요는 Md = P × L(Y, i)로 쓰며, 물가와 소득에는 같은 방향, 이자율에는 반대 방향으로 움직인다. 양변을 물가로 나눈 실질 화폐수요는 M/P = kY - hi처럼 간단히 나타낸다. k는 소득에 대한, h는 이자율에 대한 민감도이고 h가 무한대인 경우가 유동성 함정이다.','','ㅎㅍㅅㅇㅎㅅ',ARRAY['화폐수요','실질통화량','LM 곡선','유동성 함정']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "물가가 2배면 장 볼 돈도 2배,\n많이 벌수록 더 들고 다니고,\n이자율이 높으면 덜 들고 있어요."}, {"type": "table", "title": "화폐수요를 정하는 세 요인", "columns": ["요인", "관계"], "rows": [["물가 P", "같은 방향"], ["소득 Y", "같은 방향"], ["이자율 i", "반대 방향"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1144,'대부자금설','저축과 투자가 만나는 대부자금시장에서 이자율이 정해진다는 고전학파 이론','대부자금설은 이자율을 실물 경제의 저축과 투자가 같아지는 대부자금시장에서 결정되는 가격으로 본다. 저축이 늘면 빌려줄 돈이 많아져 이자율이 내리고, 투자 수요가 늘면 이자율이 오른다. 화폐시장에서 이자율이 정해진다는 케인스의 유동성 선호설과 대비된다.','','ㄷㅂㅈㄱㅅ',ARRAY['유동성 선호설','화폐의 중립성','화폐시장 균형','총저축률']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "돈을 빌려주려는 사람과 빌리려는 사람이 만나는 시장이 있어요.\n빌려줄 돈이 많으면 이자가 싸지고\n빌리려는 사람이 많으면 이자가 비싸져요."}, {"type": "table", "title": "대부자금시장", "columns": ["쪽", "누가", "무엇"], "rows": [["공급", "저축하는 가계", "빌려줄 돈"], ["수요", "투자하는 기업", "빌리려는 돈"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1145,'LM 곡선','화폐시장이 균형을 이루는 국민소득과 이자율의 조합을 이은 선','LM 곡선은 화폐수요(L)와 화폐공급(M)이 같아지는 점들을 이자율-국민소득 평면에 이은 선이다. 소득이 늘면 거래용 화폐수요가 늘어 이자율이 오르기 때문에 우상향한다. 통화량이 늘면 오른쪽(아래)으로, 물가가 올라 실질통화량이 줄면 왼쪽(위)으로 이동한다.','','Lㄱㅅ',ARRAY['IS 곡선','IS-LM 모형','화폐시장 균형','실질통화량']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "소득이 늘면 쓸 돈이 더 필요해요.\n돈은 그대로인데 찾는 사람이 많아지니 이자율이 올라요.\n이 관계를 선으로 그린 게 LM 곡선이에요."}, {"type": "flow", "title": "LM 곡선이 우상향하는 이유", "steps": ["소득↑", "화폐수요↑", "화폐공급은 그대로", "이자율↑"]}, {"type": "table", "title": "LM 곡선의 기울기", "columns": ["화폐수요의 이자율 탄력성", "LM 모양"], "rows": [["크다", "완만"], ["작다", "가파름"], ["0 (고전학파)", "수직"], ["무한대 (유동성 함정)", "수평"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1146,'실질통화량','명목통화량을 물가로 나눠 그 돈으로 실제 살 수 있는 양으로 나타낸 통화량','실질통화량은 M/P로 계산하며 실질잔고라고도 한다. 명목통화량이 그대로여도 물가가 오르면 실질통화량은 줄어 이자율이 오르고 LM 곡선이 왼쪽으로 이동한다. 반대로 물가가 내리면 실질통화량이 늘어난다.','','ㅅㅈㅌㅎㄹ',ARRAY['통화량','LM 곡선','이자율 효과','피구 효과']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "통장에 100만 원이 그대로 있어도\n물가가 2배가 되면 살 수 있는 건 절반이에요.\n이 \"실제 구매력 기준\" 돈의 양이 실질통화량이에요."}, {"type": "table", "title": "명목 100, 물가가 바뀌면", "columns": ["물가", "실질통화량"], "rows": [["100", "100"], ["125", "80"], ["80", "125"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1147,'IS-LM 모형','생산물시장과 화폐시장이 동시에 균형인 국민소득과 이자율을 찾는 모형','IS-LM 모형은 IS 곡선과 LM 곡선이 만나는 한 점에서 균형 국민소득과 균형 이자율이 함께 정해진다고 본다. 케인스의 이론을 힉스가 그래프로 정리했으며 물가가 고정된 단기를 가정한다. IS가 오른쪽으로 가면 소득과 이자율이 함께 오르고, LM이 오른쪽으로 가면 소득은 늘고 이자율은 내린다.','','ILㅁㅎ',ARRAY['IS 곡선','LM 곡선','구축효과','AD-AS 모형']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "물건 시장 선(IS)과 돈 시장 선(LM)이\n만나는 한 점이 경제의 균형이에요.\n정책이 어느 선을 움직이는지 보면 결과를 알 수 있어요."}, {"type": "table", "title": "곡선이 움직이면", "columns": ["변화", "소득", "이자율"], "rows": [["IS 오른쪽 (정부지출↑·감세)", "증가", "상승"], ["IS 왼쪽 (투자·소비 위축)", "감소", "하락"], ["LM 오른쪽 (통화량↑·물가↓)", "증가", "하락"], ["LM 왼쪽 (통화량↓·물가↑)", "감소", "상승"]]}, {"type": "text", "title": "왜 중요할까?", "body": "재정정책과 통화정책이 금리와 소득을 어떻게 바꾸는지\n한 장의 그림으로 비교할 수 있어요."}]'::jsonb,ARRAY['tesat']::text[]),
(1148,'AD-AS 모형','물가와 국민소득이 총수요와 총공급이 만나는 곳에서 정해진다고 보는 모형','AD-AS 모형은 세로축에 물가, 가로축에 국민소득을 두고 총수요(AD) 곡선과 총공급(AS) 곡선의 교점으로 경제를 설명한다. AD는 IS-LM에서 나와 우하향하고, 단기 AS는 임금·가격이 늦게 따라와 우상향, 장기 AS는 잠재GDP에서 수직이다. 총수요 정책은 AD를, 원자재값이나 기술 변화는 AS를 움직인다.','','AAㅁㅎ',ARRAY['총수요','총공급','IS-LM 모형','스태그플레이션']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "미시의 수요·공급 그래프를 나라 전체로 키운 모형이에요.\n가격 대신 물가, 수량 대신 국민소득을 봐요."}, {"type": "table", "title": "곡선별 모양과 이유", "columns": ["곡선", "모양", "이유"], "rows": [["AD", "우하향", "이자율·피구·경상수지 효과"], ["단기 AS", "우상향", "임금·가격 경직, 화폐환상"], ["장기 AS", "잠재GDP에서 수직", "가격·임금이 모두 조정"]]}, {"type": "table", "title": "무엇이 어느 곡선을 움직이나", "columns": ["요인", "이동"], "rows": [["정부지출↑·감세·통화량↑", "AD 오른쪽"], ["원자재값·임금 상승", "단기 AS 왼쪽"], ["기술 진보·자본 축적", "AS 오른쪽"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1149,'이자율 효과','물가가 내리면 실질통화량이 늘어 이자율이 떨어지고 투자가 늘어나는 효과','물가가 내리면 같은 명목통화량으로 살 수 있는 것이 많아져 실질통화량이 늘고, LM 곡선이 오른쪽으로 이동해 이자율이 내려간다. 이자율이 내리면 투자가 늘어 국민소득이 커진다. 총수요 곡선이 우하향하는 가장 중요한 이유로 케인스 효과라고도 한다.','','ㅇㅈㅇㅎㄱ',ARRAY['AD-AS 모형','실질통화량','피구 효과','경상수지 효과']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "물건 값이 싸지면 거래에 필요한 돈이 줄어\n돈이 남게 돼요.\n남는 돈이 이자율을 낮추고 투자를 늘려요."}, {"type": "flow", "title": "물가가 내리면", "steps": ["실질통화량↑", "이자율↓ (LM 오른쪽)", "투자↑", "국민소득↑"]}]'::jsonb,ARRAY['tesat']::text[]),
(1150,'경상수지 효과','국내 물가가 내리면 우리 상품이 상대적으로 싸져 순수출이 늘어나는 효과','국내 물가가 외국보다 내려가면 수출품 가격 경쟁력이 높아져 수출은 늘고 수입은 준다. 순수출이 늘면 IS 곡선이 오른쪽으로 이동해 총수요가 커진다. 이자율 효과, 피구 효과와 함께 총수요 곡선이 우하향하는 이유이며 순수출 효과라고도 한다.','','ㄱㅅㅅㅈㅎㄱ',ARRAY['AD-AS 모형','이자율 효과','피구 효과','경상수지']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "우리 물가가 내리면 외국 사람 눈엔 우리 물건이 싸 보여요.\n그래서 수출이 늘고 총수요가 커져요."}, {"type": "table", "title": "AD가 우하향하는 세 가지 이유", "columns": ["효과", "물가가 내리면"], "rows": [["이자율 효과", "이자율↓ → 투자↑"], ["피구 효과", "가진 돈의 실질가치↑ → 소비↑"], ["경상수지 효과", "상대가격↓ → 순수출↑"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1151,'화폐환상','물가 변화를 고려하지 않고 명목 금액만 보고 판단하는 착각','화폐환상은 명목임금이 오르면 물가가 더 올라 실질임금이 줄었는데도 소득이 늘었다고 느끼는 것과 같은 착각이다. 노동자가 화폐환상에 빠지면 물가 상승기에 노동 공급이 늘어 단기 총공급 곡선이 우상향하는 이유가 된다. 사람들이 물가를 정확히 예상하면 이런 효과는 사라진다.','','ㅎㅍㅎㅅ',ARRAY['실질임금','AD-AS 모형','인플레이션','합리적 기대 이론']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "월급이 5% 올라서 기뻤는데\n물가가 8% 올랐다면 사실은 손해예요.\n숫자만 보고 좋아하는 게 화폐환상이에요."}, {"type": "table", "title": "명목과 실질", "columns": ["구분", "변화"], "rows": [["명목임금", "+5%"], ["물가", "+8%"], ["실질임금", "약 -3%"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1152,'재할인율','중앙은행이 은행에 돈을 빌려줄 때 적용하는 금리','재할인율을 내리면 은행이 중앙은행에서 더 많이 빌려 통화량이 늘고 시장금리가 내려가며, 올리면 반대가 된다. 과거에는 주요 통화정책 수단이었지만 지금은 공개시장운영에 밀려 보조 수단으로 쓰인다. 중앙은행에서 돈을 빌렸다는 사실이 은행 신용에 부담이 될 수 있다는 점도 잘 쓰지 않는 이유다.','','ㅈㅎㅇㅇ',ARRAY['통화정책수단','공개시장운영','기준금리','지급준비제도']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "은행도 돈이 모자라면 한국은행에서 빌려요.\n그때 내는 이자가 재할인율이에요.\n이 이자를 싸게 하면 은행이 더 빌려 시중에 돈이 풀려요."}, {"type": "table", "title": "재할인율을 바꾸면", "columns": ["변화", "은행 행동", "결과"], "rows": [["인하", "한국은행에서 더 빌림", "통화량↑, 금리↓"], ["인상", "덜 빌림", "통화량↓, 금리↑"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1153,'중간목표 관리제','통화량이나 금리를 중간 목표로 정해 관리하며 물가 안정을 꾀하던 통화정책 방식','중간목표 관리제는 중앙은행이 직접 다룰 수 없는 물가 대신 그와 관계가 깊은 통화량 등을 목표로 두고 관리하는 방식이다. 금융시장이 복잡해지며 통화량과 물가의 관계가 불안정해지자 효과가 떨어졌다. 우리나라는 이후 물가 상승률 목표를 직접 내거는 물가안정목표제로 바꿨다.','','ㅈㄱㅁㅍㄱㄹㅈ',ARRAY['물가안정목표제','통화지표','통화주의','통화정책']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "물가를 바로 조절하기 어려우니\n물가와 연결된 통화량을 대신 목표로 삼아 관리하던 방식이에요.\n지금은 물가 목표를 직접 써요."}, {"type": "table", "title": "예전과 지금", "columns": ["방식", "목표"], "rows": [["중간목표 관리제", "통화량·금리 같은 중간 목표"], ["물가안정목표제", "소비자물가 상승률 목표 (현재 2%)"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1154,'누진세','과세 대상 금액이 커질수록 더 높은 세율을 매기는 세금','누진세는 소득이나 재산이 많을수록 세율이 올라가는 구조로, 우리나라 소득세가 대표적이다. 소득 재분배 효과가 있고, 호황에는 세금이 소득보다 빨리 늘고 불황에는 빨리 줄어 경기 변동을 자동으로 완화한다. 이 때문에 실업수당과 함께 자동안정화장치의 대표 사례로 꼽힌다.','','ㄴㅈㅅ',ARRAY['자동안정화장치','실업수당','조세부담률','재정정책']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "많이 버는 사람은 더 높은 비율로 세금을 내요.\n그래서 경기가 좋을 땐 세금이 확 늘고\n나쁠 땐 확 줄어 경기 출렁임을 줄여 줘요."}, {"type": "table", "title": "경기에 따라 저절로", "columns": ["경기", "세금", "효과"], "rows": [["호황", "소득보다 더 빨리 늘어요", "과열 진정"], ["불황", "소득보다 더 빨리 줄어요", "소비 지탱"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1155,'실업수당','일자리를 잃은 사람에게 생활 안정과 재취업을 돕기 위해 지급하는 급여','실업수당은 고용보험 등을 통해 실직자에게 일정 기간 지급하는 돈으로, 우리나라에서는 구직급여(실업급여) 형태로 운영된다. 불황에는 지급이 늘어 가처분소득 감소를 막고, 호황에는 줄어들어 경기 변동을 자동으로 완화한다. 정부가 따로 결정하지 않아도 작동하는 자동안정화장치의 대표 예다.','','ㅅㅇㅅㄷ',ARRAY['자동안정화장치','누진세','실업률','재정정책']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "일자리를 잃어도 당분간 생활비를 받아요.\n불황에 지급이 늘어 소비가 급격히 무너지는 걸 막아 줘요."}, {"type": "table", "title": "자동안정화장치로서의 역할", "columns": ["경기", "지급", "효과"], "rows": [["호황", "줄어요", "과열 완화"], ["불황", "늘어요", "소비 지탱"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1156,'리카도 대등정리','정부지출이 같다면 세금으로 걷든 국채로 빌리든 경제 효과가 같다는 이론','국채를 발행해 세금을 깎아 주면 사람들은 나중에 국채를 갚기 위해 세금이 오를 것으로 예상하고 늘어난 소득을 저축한다. 그래서 소비가 늘지 않고 감세의 경기 부양 효과가 사라진다는 것이 이 이론의 결론이다. 현실에서는 유동성 제약, 근시안적 소비, 세대 간 부담 이전 때문에 잘 맞지 않는다는 비판이 있다.','','ㄹㅋㄷㄷㄷㅈㄹ',ARRAY['유동성 제약','재정정책','국채','합리적 기대 이론']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "정부가 빚을 내서 세금을 깎아 줘도\n\"나중에 세금으로 갚겠구나\" 하고 저축하면\n소비는 그대로예요."}, {"type": "flow", "title": "국채로 감세하면", "steps": ["오늘 세금↓, 가처분소득↑", "미래 증세를 예상", "늘어난 소득을 저축", "소비 그대로"]}, {"type": "table", "title": "현실에서 잘 안 맞는 이유", "columns": ["이유", "내용"], "rows": [["유동성 제약", "돈을 빌리기 어려운 사람은 감세분을 바로 써요"], ["근시안", "먼 미래 세금까지 계산하지 않아요"], ["세대 차이", "미래 세대가 갚는다고 보면 지금 소비를 늘려요"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1157,'내부시차','경제 문제가 생긴 뒤 이를 알아채고 정책을 결정해 실행하기까지 걸리는 시간','내부시차는 상황을 인식하는 시간과 정책을 결정하고 집행하는 시간을 합친 것이다. 재정정책은 예산 편성과 국회 의결을 거쳐야 해 내부시차가 길다. 통화정책은 금융통화위원회가 비교적 빠르게 결정할 수 있어 내부시차가 짧다.','','ㄴㅂㅅㅊ',ARRAY['외부시차','정책시차','재정정책','통화정책']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "아픈 걸 알아채고 병원에 가서 처방받기까지 걸리는 시간이에요.\n약을 먹은 뒤 낫기까지는 외부시차예요."}, {"type": "table", "title": "내부시차와 외부시차", "columns": ["시차", "뜻", "긴 쪽"], "rows": [["내부시차", "알아채고 실행하기까지", "재정정책"], ["외부시차", "실행 후 효과가 나타나기까지", "통화정책"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1158,'외부시차','정책을 실행한 뒤 실제로 경제에 효과가 나타나기까지 걸리는 시간','외부시차는 정책이 집행된 뒤 소비, 투자, 고용 같은 실물 경제에 영향이 퍼지기까지의 시간이다. 통화정책은 금리를 바꿔도 기업과 가계가 계획을 바꾸고 실행하는 데 시간이 걸려 외부시차가 길다. 재정정책은 정부가 직접 돈을 쓰기 때문에 외부시차가 상대적으로 짧다.','','ㅇㅂㅅㅊ',ARRAY['내부시차','정책시차','통화정책 파급경로','기준금리']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "약을 먹고 효과가 나타나기까지 걸리는 시간이에요.\n금리를 내려도 공장이 실제로 지어지기까지는 한참 걸려요."}, {"type": "table", "title": "정책별 시차 비교", "columns": ["정책", "결정(내부시차)", "효과(외부시차)"], "rows": [["재정정책", "느림", "빠름"], ["통화정책", "빠름", "느림"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1159,'통화주의','통화량이 물가와 경기를 좌우한다고 보고 규칙적인 통화 공급을 주장한 학파','통화주의는 밀턴 프리드먼을 중심으로 한 시카고학파가 화폐수량설을 새로 다듬어 발전시켰다. 정부가 그때그때 판단하는 재량적 정책보다 통화량을 일정한 비율로 늘리는 준칙을 강조했다. 인플레이션은 언제 어디서나 화폐적 현상이라는 주장으로 유명하다.','','ㅌㅎㅈㅇ',ARRAY['통화량','화폐의 중립성','중간목표 관리제','케인스 국민소득 결정이론']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "정부가 경기를 보며 이리저리 돈을 풀고 거두기보다\n매년 정해진 만큼만 꾸준히 늘리자는 생각이에요."}, {"type": "table", "title": "학파별로 더 믿는 정책", "columns": ["학파", "정책", "이유"], "rows": [["케인스학파", "재정정책", "불황엔 금리를 내려도 투자가 잘 안 늘어요"], ["통화주의", "통화정책 (준칙)", "재량 개입보다 일정한 통화 공급이 안정적이에요"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1160,'야성적 충동','기업가의 투자 결정을 움직이는 낙관이나 비관 같은 심리적 요인','케인스는 투자가 이자율보다 미래에 대한 기대와 자신감, 즉 야성적 충동(animal spirits)에 더 크게 좌우된다고 봤다. 경기 전망이 어두우면 금리를 내려도 투자가 잘 늘지 않는 이유가 여기에 있다. 이 때문에 케인스학파는 불황기에 통화정책보다 재정정책을 더 중시했다.','','ㅇㅅㅈㅊㄷ',ARRAY['케인스 국민소득 결정이론','통화정책','재정정책','소비자심리지수']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "금리가 싸도 \"앞으로 장사가 안 될 것 같다\"고 느끼면\n사장님은 공장을 짓지 않아요.\n투자는 계산만큼 마음이 움직여요."}, {"type": "table", "title": "투자를 정하는 것", "columns": ["학파", "생각"], "rows": [["고전학파", "이자율이 내리면 빌려서 투자해요"], ["케인스", "미래 전망, 야성적 충동이 더 중요해요"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1161,'유동성 제약','미래 소득이 있어도 지금 돈을 빌리기 어려워 원하는 만큼 소비하지 못하는 상태','유동성 제약에 놓인 가계는 신용이나 담보가 부족해 대출을 받기 어렵기 때문에 현재 소득에 맞춰 소비할 수밖에 없다. 이런 가계는 감세나 지원금을 받으면 저축하지 않고 바로 쓰는 경향이 강하다. 그래서 유동성 제약이 클수록 리카도 대등정리가 잘 성립하지 않는다.','','ㅇㄷㅅㅈㅇ',ARRAY['리카도 대등정리','한계소비성향','재정정책','유동성']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "내년에 월급이 오를 걸 알아도\n지금 은행이 돈을 안 빌려주면 지금 쓸 수 없어요.\n그래서 돈이 생기면 바로 써요."}, {"type": "table", "title": "감세 100만 원을 받으면", "columns": ["가계", "행동"], "rows": [["유동성 제약 없음", "미래 세금을 생각해 일부 저축"], ["유동성 제약 있음", "대부분 바로 소비"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1162,'정책 무력성 명제','사람들이 합리적으로 예상한 총수요 정책은 단기에도 소득을 늘리지 못한다는 주장','루카스, 사전트 같은 새고전학파는 사람들이 합리적 기대를 하고 가격과 임금이 신축적이면 미리 예상된 정책은 곧바로 임금과 가격에 반영된다고 봤다. 그래서 예상된 통화 확대는 물가만 올리고 생산과 고용은 늘리지 못한다. 예상하지 못한 정책만 잠깐 효과가 있다는 것이 이 주장의 핵심이다.','','ㅈㅊㅁㄹㅅㅁㅈ',ARRAY['합리적 기대 이론','화폐의 중립성','통화정책','잠재GDP성장률']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "\"돈을 풀겠다\"고 미리 알리면\n사람들이 물가 상승을 예상해 임금과 가격을 먼저 올려요.\n결국 생산은 그대로, 물가만 올라요."}, {"type": "table", "title": "정책 종류별 효과", "columns": ["정책", "효과"], "rows": [["미리 예상된 정책", "단기에도 효과 없음"], ["예상 못한 정책", "잠깐 효과가 있다가 사라짐"]]}, {"type": "text", "title": "왜 중요할까?", "body": "정책을 자주 바꾸기보다 신뢰할 수 있는 규칙을 지키는 게 중요하다는\n주장의 근거가 돼요."}]'::jsonb,ARRAY['tesat']::text[]),
(1163,'취업률','경제활동인구 가운데 실제로 일하고 있는 사람의 비율','취업률은 취업자를 경제활동인구로 나눈 값으로, 100에서 실업률을 뺀 것과 같다. 분모가 생산가능인구인 고용률과는 다른 지표다. 그래서 실업률이 0%면 취업률은 100%이지만 고용률은 100%가 아닐 수 있다.','','ㅊㅇㄹ',ARRAY['실업률','고용률','경제활동참가율','비경제활동인구']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "일하려는 사람 100명 중 95명이 일하고 있으면 취업률은 95%예요.\n나머지 5명이 실업자라서 실업률은 5%고요.\n취업률 + 실업률 = 100%예요."}, {"type": "table", "title": "헷갈리는 세 지표", "columns": ["지표", "공식"], "rows": [["취업률", "취업자 ÷ 경제활동인구 × 100"], ["실업률", "실업자 ÷ 경제활동인구 × 100"], ["고용률", "취업자 ÷ 생산가능인구 × 100"]], "caption": "취업률과 실업률은 분모가 같고, 고용률만 분모가 생산가능인구예요."}]'::jsonb,ARRAY['tesat']::text[]),
(1164,'구조적 실업','기술 발달이나 산업 구조 변화로 일자리 자체가 사라져 생기는 실업','구조적 실업은 산업이 바뀌면서 기존 기술을 가진 노동자가 새 일자리에 맞지 않아 생기는 실업이다. 비자발적이고 오래가는 경우가 많으며, 마찰적 실업과 함께 자연실업률을 이룬다. 직업 재교육과 훈련으로 줄일 수 있다.','','ㄱㅈㅈㅅㅇ',ARRAY['마찰적 실업','경기적 실업','자연실업률','비자발적 실업']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "무인 계산대가 늘면 계산원 일자리가 줄어요.\n경기가 좋아져도 그 일자리는 잘 돌아오지 않아요.\n새 기술을 배워야 다시 일할 수 있어요."}, {"type": "table", "title": "실업의 세 가지 종류", "columns": ["종류", "원인", "대책"], "rows": [["마찰적 실업", "일자리를 찾는 과정", "일자리 정보망"], ["구조적 실업", "산업 구조 변화", "직업 재교육·훈련"], ["경기적 실업", "경기 침체", "재정·통화정책"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1165,'경기적 실업','경기 침체로 기업이 생산을 줄이면서 일자리가 줄어 생기는 실업','경기적 실업은 불황으로 총수요가 줄어 생기는 비자발적 실업이다. 경기가 회복되면 줄어들고, 재정정책과 통화정책으로 총수요를 늘려 대응한다. 경기적 실업이 0인 상태를 완전고용이라고 한다.','','ㄱㄱㅈㅅㅇ',ARRAY['구조적 실업','완전고용','자연실업률','오쿤의 법칙']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "불황이 오면 물건이 덜 팔려서 회사가 사람을 덜 뽑아요.\n그래서 생기는 실업이에요.\n경기가 살아나면 다시 줄어들어요."}, {"type": "text", "title": "왜 중요할까?", "body": "정부와 중앙은행이 경기 부양책으로 줄일 수 있는 실업은 주로 경기적 실업이에요.\n완전고용은 실업자가 0명이 아니라 경기적 실업이 0인 상태예요."}]'::jsonb,ARRAY['tesat']::text[]),
(1166,'오쿤의 법칙','실업률이 오르면 실제 GDP가 잠재GDP보다 줄어드는 경험적 관계','오쿤의 법칙은 실업률과 GDP 사이의 반대 방향 관계를 보여 주는 경험 법칙이다. 실업률이 자연실업률보다 높아지면 실제 GDP는 잠재GDP에 못 미치게 된다. 일하는 사람이 줄면 생산도 줄어든다는 직관을 숫자로 나타낸 것이다.','','ㅇㅋㅇㅂㅊ',ARRAY['실업률','GDP갭','실업률갭','경기적 실업']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "일하는 사람이 줄면 만들어지는 물건도 줄어요.\n그래서 실업률이 오르면 GDP는 내려가요.\n두 지표가 반대로 움직이는 관계예요."}, {"type": "flow", "title": "오쿤의 법칙 흐름", "steps": ["경기 침체", "실업률↑", "생산 감소", "실제 GDP < 잠재GDP"]}]'::jsonb,ARRAY['tesat']::text[]),
(1167,'비자발적 실업','현재 임금 수준에서 일할 뜻이 있는데도 일자리를 얻지 못한 상태','비자발적 실업은 일할 의사와 능력이 있지만 일자리가 없어 일하지 못하는 실업이다. 구조적 실업과 경기적 실업이 여기에 속한다. 스스로 더 나은 일자리를 찾는 자발적 실업과 구분된다.','','ㅂㅈㅂㅈㅅㅇ',ARRAY['자발적 실업','구조적 실업','경기적 실업','마찰적 실업']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "일하고 싶고 지금 임금도 받아들일 수 있는데 자리가 없는 경우예요.\n본인 선택이 아니라 일자리가 부족해서 생겨요."}, {"type": "table", "title": "자발적 vs 비자발적", "columns": ["구분", "예"], "rows": [["자발적 실업", "더 좋은 조건을 찾아 이직 준비 (마찰적 실업)"], ["비자발적 실업", "산업 변화·불황으로 일자리를 잃음 (구조적·경기적 실업)"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1168,'라스파이레스 지수','기준연도 구입량을 가중치로 고정해 물가 변화를 재는 방식','라스파이레스 지수는 기준연도 수량을 그대로 두고 비교연도 가격으로 다시 계산해 물가를 잰다. 소비자물가지수와 생산자물가지수가 이 방식이다. 값이 오른 상품을 덜 사는 대체 효과를 반영하지 못해 물가 상승을 과대평가하는 경향이 있다.','','ㄹㅅㅍㅇㄹㅅㅈㅅ',ARRAY['파셰 지수','소비자물가지수(CPI)','생산자물가지수(PPI)','물가지수']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "작년에 산 장바구니를 그대로 올해 가격으로 다시 사 봐요.\n그 비용이 얼마나 늘었는지가 물가 상승이에요.\n비싸진 물건을 덜 사는 건 반영이 안 돼요."}, {"type": "table", "title": "두 가지 물가지수 방식", "columns": ["방식", "가중치", "대표 지표", "편향"], "rows": [["라스파이레스", "기준연도 수량", "CPI·PPI", "과대평가"], ["파셰", "비교연도 수량", "GDP디플레이터", "과소평가"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1169,'파셰 지수','비교연도 구입량을 가중치로 써서 물가 변화를 재는 방식','파셰 지수는 비교연도 수량을 가중치로 삼아 그 수량을 지금 가격과 기준연도 가격으로 각각 계산해 비교한다. GDP디플레이터가 이 방식으로 계산된다. 소비 구성이 바뀐 결과를 반영하기 때문에 물가 상승을 과소평가하는 경향이 있다.','','ㅍㅅㅈㅅ',ARRAY['라스파이레스 지수','GDP디플레이터','물가지수']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "올해 실제로 산 장바구니를 기준으로 작년 가격과 올해 가격을 비교해요.\n비싸진 물건을 이미 덜 산 뒤라서 상승폭이 작게 나와요."}, {"type": "flow", "title": "파셰 지수 계산", "steps": ["올해 수량 고정", "올해 가격으로 계산", "기준연도 가격으로 계산", "두 값의 비율 × 100"]}]'::jsonb,ARRAY['tesat']::text[]),
(1170,'소득정책','임금과 가격 상승을 정부가 직접 억제해 물가를 잡으려는 정책','소득정책은 비용 인상 인플레이션에 대응해 임금 인상률과 가격 인상을 억누르는 정책이다. 총수요를 줄이지 않고 물가를 잡으려는 시도지만, 정부가 임금과 이윤을 직접 통제하기 어렵다는 한계가 있다. 근본 대책으로는 생산성을 높여 총공급을 늘리는 정책이 함께 거론된다.','','ㅅㄷㅈㅊ',ARRAY['비용인상 인플레이션','스태그플레이션','총공급','임금피크제']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "임금이 오르면 물건값이 오르고, 그러면 또 임금을 올려 달라는 악순환이 생겨요.\n정부가 이 고리를 끊으려고 임금·가격 인상을 누르는 게 소득정책이에요."}, {"type": "table", "title": "비용 인상 인플레이션 대책", "columns": ["정책", "방법", "한계"], "rows": [["소득정책", "임금·가격 상승 억제", "직접 통제가 어려워요"], ["총공급 정책", "기술 혁신·생산성 향상", "시간이 오래 걸려요"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1171,'구두창 비용','물가가 오를 때 현금을 덜 들고 은행을 자주 오가며 드는 시간과 수고','구두창 비용은 인플레이션으로 현금을 들고 있으면 손해를 보니 사람들이 현금 보유를 줄이면서 생기는 비용이다. 은행에 자주 가느라 구두 밑창이 닳는다는 비유에서 나온 이름이다. 예상된 인플레이션에서도 생기는 사회적 비용이다.','','ㄱㄷㅊㅂㅇ',ARRAY['메뉴비용','인플레이션','인플레이션 조세','하이퍼인플레이션']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "물가가 빨리 오르면 지갑 속 현금 가치가 금방 줄어요.\n그래서 조금씩 자주 찾아 쓰느라 시간과 발품이 들어요.\n이 수고가 구두창 비용이에요."}, {"type": "table", "title": "인플레이션의 비용 비교", "columns": ["비용", "뜻"], "rows": [["구두창 비용", "현금 관리에 드는 수고"], ["메뉴비용", "가격표를 바꾸는 비용"], ["인플레이션 조세", "화폐 구매력 감소"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1172,'인플레이션 조세','정부가 화폐를 찍어 쓰면서 민간이 가진 돈의 구매력이 줄어드는 효과','인플레이션 조세는 정부가 통화를 발행해 재원을 마련할 때 물가가 올라 민간 화폐의 실질가치가 줄어드는 현상이다. 세금을 걷지 않아도 사실상 국민에게 세금을 매긴 것과 같은 효과가 난다. 심하면 하이퍼인플레이션으로 이어진다.','','ㅇㅍㄹㅇㅅㅈㅅ',ARRAY['시뇨리지','하이퍼인플레이션','구두창 비용','인플레이션']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "정부가 돈을 많이 찍어 쓰면 물가가 올라요.\n내 지갑 속 만 원으로 살 수 있는 게 줄어들죠.\n세금을 낸 것처럼 내 몫이 줄어든 셈이에요."}, {"type": "flow", "title": "인플레이션 조세 흐름", "steps": ["정부 화폐 발행", "통화량 증가", "물가 상승", "민간 화폐 구매력↓"]}]'::jsonb,ARRAY['tesat']::text[]),
(1173,'희생비율','인플레이션율을 1%p 낮추는 대가로 줄어드는 실질 GDP의 비율','희생비율은 물가상승률을 1%p 낮추려면 생산을 몇 % 포기해야 하는지를 나타낸다. 단기 필립스곡선이 보여 주는 물가와 실업의 상충 관계를 비용으로 바꿔 본 지표다. 정책 신뢰가 높아 기대인플레이션이 빨리 내려가면 희생비율은 작아진다.','','ㅎㅅㅂㅇ',ARRAY['필립스곡선','디스인플레이션','기대인플레이션','실업률']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "물가를 잡으려고 금리를 올리면 경기가 식어요.\n물가상승률 1%p를 낮추는 데 GDP가 몇 % 줄었는지가 희생비율이에요."}, {"type": "text", "title": "왜 중요할까?", "body": "중앙은행이 물가를 잡을 때 경기 희생을 얼마나 감수해야 하는지 가늠하게 해 줘요."}]'::jsonb,ARRAY['tesat']::text[]),
(1174,'72의 법칙','72를 연 성장률로 나눠 규모가 두 배가 되는 기간을 어림하는 방법','72의 법칙은 복리로 불어나는 값이 두 배가 되는 데 걸리는 햇수를 72 ÷ 증가율로 간단히 구하는 계산법이다. 경제성장률뿐 아니라 이자율, 물가상승률에도 쓸 수 있다. 증가율이 낮을수록 실제 값과 잘 맞는다.','','7ㅇㅂㅊ',ARRAY['복리','경제성장률']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "연 4%씩 크면 72 ÷ 4 = 18년 뒤에 두 배가 돼요.\n이자율 6%짜리 예금이면 약 12년 뒤 원금이 두 배예요."}, {"type": "table", "title": "72의 법칙 vs 실제 계산", "columns": ["성장률", "72의 법칙", "실제"], "rows": [["3%", "약 24년", "약 23.4년"], ["4%", "약 18년", "약 17.7년"], ["7%", "약 10년", "약 10.2년"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1175,'인플레이션 갭','실제 GDP가 잠재GDP를 웃돌아 경기가 과열된 상태의 차이','인플레이션 갭은 실제 생산이 물가를 자극하지 않고 지속할 수 있는 수준을 넘어선 상태를 말한다. GDP갭이 플러스인 경우로, 물가 상승 압력이 커진다. 총수요를 억제하는 긴축 정책이 대책이 된다.','','ㅇㅍㄹㅇㅅㄱ',ARRAY['디플레이션 갭','GDP갭','잠재GDP성장률','수요견인 인플레이션']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "경제가 무리 없이 낼 수 있는 속도보다 더 빨리 달리는 상태예요.\n엔진이 과열되듯 물가가 오르기 쉬워요."}, {"type": "table", "title": "두 가지 갭", "columns": ["갭", "상태", "대책"], "rows": [["인플레이션 갭", "실제 > 잠재, 과열", "총수요 억제"], ["디플레이션 갭", "실제 < 잠재, 부진", "경기 부양"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1176,'디플레이션 갭','실제 GDP가 잠재GDP에 못 미쳐 경기가 부진한 상태의 차이','디플레이션 갭은 실제 생산이 잠재GDP보다 적어 설비와 노동이 놀고 있는 상태다. GDP갭이 마이너스인 경우로, 실업이 늘고 물가 하락 압력이 생긴다. 재정·통화정책으로 총수요를 늘려 경기를 부양하는 것이 대책이다.','','ㄷㅍㄹㅇㅅㄱ',ARRAY['인플레이션 갭','GDP갭','경기적 실업','디플레이션']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "공장과 일손은 남는데 물건이 덜 팔리는 상태예요.\n경제가 낼 수 있는 힘보다 덜 쓰고 있는 거예요."}, {"type": "flow", "title": "디플레이션 갭 대응", "steps": ["실제 GDP < 잠재GDP", "실업↑·물가 압력↓", "재정·통화 확장", "총수요 회복"]}]'::jsonb,ARRAY['tesat']::text[]),
(1177,'성장회계','경제성장률을 노동·자본·기술 각각의 기여로 나눠 보는 분석 방법','성장회계는 생산함수 Y = A × F(K, L)을 바탕으로 성장률을 노동 투입, 자본 투입, 총요소생산성의 기여로 쪼갠다. 노동과 자본 기여를 빼고 남는 부분을 솔로 잔차라고 하며, 이것이 총요소생산성 증가로 해석된다. 성장이 투입 확대 덕인지 생산성 향상 덕인지 판단하는 데 쓴다.','','ㅅㅈㅎㄱ',ARRAY['총요소생산성(TFP)','노동생산성','경제성장률','솔로 모형']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "성장률 5%가 어디서 왔는지 영수증처럼 나눠 보는 거예요.\n사람이 늘어서, 기계가 늘어서, 기술이 좋아져서 각각 얼마인지 따져요."}, {"type": "table", "title": "성장률 5%를 쪼개면 (예시)", "columns": ["요인", "기여"], "rows": [["노동 투입 증가", "1%p"], ["자본 투입 증가", "2%p"], ["나머지 (솔로 잔차)", "2%p"]], "caption": "노동과 자본으로 설명 못 하는 나머지가 기술·제도의 기여예요."}]'::jsonb,ARRAY['tesat']::text[]),
(1178,'솔로 모형','저축과 자본 축적, 인구 증가, 기술로 장기 성장을 설명하는 신고전파 모형','솔로 모형은 자본이 늘수록 추가 효과가 줄어드는 한계생산 체감을 가정해 장기 성장을 설명한다. 자본 축적만으로는 1인당 소득이 계속 늘 수 없고 결국 균제상태에 이른다. 따라서 1인당 소득의 지속적 성장은 기술 진보에서 나온다고 본다.','','ㅅㄹㅁㅎ',ARRAY['균제상태','황금률','총요소생산성(TFP)','성장회계']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "기계를 계속 늘리면 처음엔 생산이 쑥 늘지만 점점 덜 늘어요.\n그래서 결국 기계만으로는 더 잘살 수 없고 기술이 좋아져야 해요."}, {"type": "flow", "title": "솔로 모형의 결론", "steps": ["저축 → 자본 축적", "자본 효과 체감", "균제상태 도달", "지속 성장은 기술 진보"]}]'::jsonb,ARRAY['tesat']::text[]),
(1179,'균제상태','저축으로 쌓는 자본이 감가상각과 인구 증가분을 딱 메워 1인당 자본이 멈춘 상태','균제상태는 솔로 모형에서 새 투자가 마모된 자본과 늘어난 인구에 필요한 자본을 겨우 채우는 지점이다. 이때 1인당 생산과 자본은 더 늘지 않고, 총생산은 인구 증가율만큼 계속 늘어난다. 기술이 진보하면 균제상태 자체가 위로 옮겨 간다.','','ㄱㅈㅅㅌ',ARRAY['솔로 모형','황금률','총요소생산성(TFP)']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "물이 들어오는 만큼 빠져나가 수위가 그대로인 욕조와 비슷해요.\n1인당 생산이 더 늘지도 줄지도 않아요."}, {"type": "table", "title": "균제상태에서는", "columns": ["항목", "변화"], "rows": [["1인당 생산·자본", "멈춰요"], ["총생산", "인구 증가율만큼 늘어요"], ["기술 진보가 있으면", "균제상태가 위로 이동"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1180,'황금률','여러 균제상태 가운데 1인당 소비가 가장 커지는 자본 수준','황금률은 솔로 모형에서 저축률에 따라 달라지는 균제상태 중 1인당 소비를 최대로 만드는 상태다. 저축이 너무 적으면 자본이 부족하고, 너무 많으면 쓸 몫이 줄어 소비가 오히려 작아진다. 균제상태가 생산 정지 상태라면 황금률은 그중 소비가 최대인 곳이다.','','ㅎㄱㄹ',ARRAY['균제상태','솔로 모형','총저축률']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "다 저축하면 쓸 돈이 없고, 다 쓰면 미래가 없어요.\n둘 사이에서 사람들이 가장 많이 쓸 수 있는 지점이 황금률이에요."}, {"type": "table", "title": "균제상태 vs 황금률", "columns": ["개념", "뜻"], "rows": [["균제상태", "1인당 생산이 멈춘 상태"], ["황금률", "그 가운데 1인당 소비가 최대"]]}]'::jsonb,ARRAY['tesat']::text[])
